import http from 'http';
import { WebSocket, WebSocketServer } from 'ws';
import { URL } from 'url';

interface FeatureFlags {
  enableCompression: boolean;
  allowChunkedUpgrade: boolean;
  strictHeaderParsing: boolean;
  maxHeaderSize: number;
}

const featureFlags: FeatureFlags = {
  enableCompression: true,
  allowChunkedUpgrade: true,
  strictHeaderParsing: true,
  maxHeaderSize: 8192
};

// Allowlist of permitted WebSocket origins to prevent Cross-Site WebSocket Hijacking
const ALLOWED_ORIGINS = new Set<string>([
  'http://localhost:3000',
  'https://localhost:3000'
]);

function isAllowedOrigin(origin: string | undefined): boolean {
  // Reject requests with no Origin header or an origin not on the allowlist
  if (!origin) return false;
  return ALLOWED_ORIGINS.has(origin);
}

function parseContentLength(headers: http.IncomingHttpHeaders): number {
  const cl = headers['content-length'];
  if (cl === undefined) return 0;
  if (Array.isArray(cl)) {
    // Always reject duplicate Content-Length headers
    throw new Error('Duplicate Content-Length headers');
  }
  const parsed = parseInt(cl, 10);
  if (isNaN(parsed) || parsed < 0) {
    throw new Error('Invalid Content-Length value');
  }
  return parsed;
}

function getTransferEncoding(headers: http.IncomingHttpHeaders): string | null {
  const te = headers['transfer-encoding'];
  if (!te) return null;
  const value = Array.isArray(te) ? te.join(', ') : te;
  return value.toLowerCase();
}

function shouldProcessBody(method: string, headers: http.IncomingHttpHeaders): boolean {
  if (method === 'GET' || method === 'HEAD') return false;
  const te = getTransferEncoding(headers);
  const cl = parseContentLength(headers);
  // RFC 7230 Section 3.3.3: If both TE and CL present, reject the message
  if (te && te.includes('chunked') && cl > 0) {
    throw new Error('Request must not contain both Transfer-Encoding and Content-Length');
  }
  return cl > 0 || te !== null;
}

function computeBodyLength(headers: http.IncomingHttpHeaders): number {
  const te = getTransferEncoding(headers);
  const cl = parseContentLength(headers);

  // Reject ambiguous requests regardless of feature flags
  if (te && te.includes('chunked') && cl > 0) {
    throw new Error('Ambiguous body framing: both TE chunked and Content-Length present');
  }

  if (te && te.includes('chunked')) {
    return -1; // chunked: read until terminator
  }
  return cl;
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);

  if (url.pathname === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok', flags: featureFlags }));
    return;
  }

  if (url.pathname === '/api/flags' && req.method === 'POST') {
    let body = '';
    let bodyLength: number;
    try {
      bodyLength = computeBodyLength(req.headers);
    } catch (e) {
      res.writeHead(400);
      res.end((e as Error).message);
      return;
    }

    if (bodyLength === 0) {
      res.writeHead(400);
      res.end('Missing body');
      return;
    }

    req.on('data', (chunk: Buffer) => {
      body += chunk.toString();
      if (body.length > featureFlags.maxHeaderSize) {
        res.writeHead(413);
        res.end('Body too large');
        req.destroy();
      }
    });

    req.on('end', () => {
      try {
        const updates = JSON.parse(body);
        // Only allow updating known safe flags
        const allowedKeys: (keyof FeatureFlags)[] = ['enableCompression', 'maxHeaderSize'];
        for (const key of Object.keys(updates)) {
          if (!allowedKeys.includes(key as keyof FeatureFlags)) {
            res.writeHead(403);
            res.end(`Cannot modify flag: ${key}`);
            return;
          }
        }
        Object.assign(featureFlags, updates);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(featureFlags));
      } catch (e) {
        res.writeHead(400);
        res.end('Invalid JSON');
      }
    });
    return;
  }

  res.writeHead(404);
  res.end('Not Found');
});

const wss = new WebSocketServer({ noServer: true });

server.on('upgrade', (req, socket, head) => {
  const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);

  if (url.pathname !== '/ws') {
    socket.write('HTTP/1.1 404 Not Found\r\n\r\n');
    socket.destroy();
    return;
  }

  // Validate the Origin header to prevent Cross-Site WebSocket Hijacking (CWE-1385)
  const origin = Array.isArray(req.headers.origin)
    ? req.headers.origin[0]
    : req.headers.origin;
  if (!isAllowedOrigin(origin)) {
    socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
    socket.destroy();
    return;
  }

  // Reject upgrade requests with ambiguous body framing
  const te = getTransferEncoding(req.headers);
  const cl = req.headers['content-length'];
  if (te || cl) {
    socket.write('HTTP/1.1 400 Bad Request\r\n\r\n');
    socket.destroy();
    return;
  }

  // Only pass the head buffer directly - no body consumption logic
  wss.handleUpgrade(req, socket, head, (ws) => {
    wss.emit('connection', ws, req);
  });
});

wss.on('connection', (ws: WebSocket, req: http.IncomingMessage) => {
  ws.on('message', (data: Buffer) => {
    const msg = data.toString();
    ws.send(`echo: ${msg}`);
  });

  ws.on('error', (err) => {
    console.error('WebSocket error:', err.message);
  });
});

server.listen(3000, () => {
  console.log('Server running on port 3000');
});

export { server, featureFlags };
